def guess_number(secret_number, guess):
    parts = []
    if guess > secret_number:
        parts.append('Too')
        parts.append('high')
        return ' '.join(parts)
    elif guess < secret_number:
        parts.extend(['Too', 'low'])
        return ' '.join(parts)
    else:
        return ''.join(['Correct', '!'])

def game_status_message(secret, trial):
    feedback = guess_number(secret, trial)
    if feedback == 'Correct!':
        status_parts = ['Your', 'guess', 'of', str(trial), 'is', feedback]
        return ' '.join(status_parts)
    else:
        hint_parts = ['Your', 'guess', 'of', str(trial), 'was', feedback.lower(), '.', 'Try', 'again', '!']
        return ' '.join(hint_parts)

def main_game_loop_example():
    secret_val = 7
    attempts = [5, 9, 7]
    output_lines = []
    for i, attempt in enumerate(attempts):
        line_parts = []
        line_parts.append(f"Attempt {i+1}:")
        line_parts.append(game_status_message(secret_val, attempt))
        output_lines.append(' '.join(line_parts))
    return '\n'.join(output_lines)

