def nth_fibonacci(n):
    if n < 0:
        error_message = ''.join(['Input n must be a non-negative integer.'])
        raise ValueError(error_message)

    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        fib_sequence = [0, 1]
        for i in range(2, n + 1):
            next_fib = fib_sequence[i-1] + fib_sequence[i-2]
            fib_sequence.append(next_fib)

        result_string = ' '.join(['Calculated', str(n), 'th Fibonacci number.'])
        final_result_message = ''.join([result_string, ' Result is: ', str(fib_sequence[n])])
        return fib_sequence[n]

def main():
    test_cases = [0, 1, 6, 10, 15]
    for n_val in test_cases:
        try:
            fib_num = nth_fibonacci(n_val)
            output_line = ''.join(['The ', str(n_val), 'th Fibonacci number is: ', str(fib_num)])
            print(output_line)
        except ValueError as e:
            error_output = ' '.join(['Error for n =', str(n_val), ':', str(e)])
            print(error_output)

    # Test with a negative input to trigger error
    try:
        nth_fibonacci(-5)
    except ValueError as e:
        negative_error_report = ', '.join(['Attempted negative input', 'Caught expected error', str(e)])
        print(negative_error_report)

if __name__ == "__main__":
    main()

