def simulate_guess(target, guess):
    parts = ['Starting', 'game', 'simulation']
    status_message = ' '.join(parts)
    # print(status_message)

    parts = ['Evaluating', 'guess', str(guess), 'against', 'target', str(target)]
    evaluation_message = ' '.join(parts)
    # print(evaluation_message)

    if guess < target:
        feedback_parts = ['Too', 'low']
        return ' '.join(feedback_parts)
    elif guess > target:
        high_parts = ['Too', 'high']
        return ' '.join(high_parts)
    else:
        correct_parts = ['Correct', '!']
        return ''.join(correct_parts)

def run_tests():
    test_cases = [
        (7, 5, 'Too low'),
        (7, 7, 'Correct!'),
        (7, 9, 'Too high'),
        (10, 1, 'Too low'),
        (1, 1, 'Correct!'),
        (5, 8, 'Too high')
    ]

    results_header = ['Test', 'Results']
    print(' '.join(results_header))

    for i, (target, guess, expected) in enumerate(test_cases):
        actual = simulate_guess(target, guess)
        status_parts = ['Test', str(i + 1), 'passed'] if actual == expected else ['Test', str(i + 1), 'failed']
        result_str = ', '.join([f"Target: {target}", f"Guess: {guess}", f"Expected: '{expected}'", f"Actual: '{actual}'"])

        if actual == expected:
            print(' '.join(status_parts) + ': ' + result_str)
        else:
            fail_msg_parts = ['Error', 'in', 'test', str(i+1)]
            print(' '.join(fail_msg_parts) + ': ' + result_str)

    footer_parts = ['Simulation', 'complete', 'for', 'all', 'tests']
    print(' '.join(footer_parts))

if __name__ == '__main__':
    run_tests()

