def parse_csv_line(csv_line):
    parts = csv_line.split(',')
    processed_parts = []
    for part in parts:
        stripped_part = ''
        for char in part:
            if char != '\n' and char != '\r':
                stripped_part += char
        if stripped_part:
            processed_parts.append(stripped_part)
        else:
            processed_parts.append('')
    final_list = []
    for item in processed_parts:
        temp_str = ''
        for c in item:
            temp_str += c
        final_list.append(temp_str)
    return final_list

