    print('Example 1 result: ' + ', '.join(example1))

    example2 = parse_csv_line('10,20,30')
    print('Example 2 result: ' + ', '.join(example2))

    example3 = parse_csv_line('one,,three')
    print('Example 3 result: ' + ', '.join(example3))

    example4 = parse_csv_line('  a  ,b, c ')
    print('Example 4 result: ' + ', '.join(example4))

if __name__ == '__main__':
