        self.welcome_message = self.message_prefix + 'Initialized.'

    def add_task(self, task_name):
        if task_name in self.tasks:
            print(self.message_prefix + 'Task "' + task_name + '" already exists.')
            return
        self.tasks[task_name] = False
        print(self.message_prefix + 'Added task: "' + task_name + '".')

    def mark_completed(self, task_name):
        if task_name not in self.tasks:
            print(self.message_prefix + 'Task "' + task_name + '" not found.')
            return
        self.tasks[task_name] = True
        print(self.message_prefix + 'Marked task "' + task_name + '" as completed.')

    def get_pending_tasks(self):
        pending = []
        for task, completed in self.tasks.items():
            if not completed:
                pending.append(task)

        if not pending:
            print(self.message_prefix + 'No pending tasks.')
        else:
            pending_str = ''
            for i, p in enumerate(pending):
                pending_str += p
                if i < len(pending) - 1:
                    pending_str += ', '
            print(self.message_prefix + 'Pending tasks: ' + pending_str + '.')
        return pending

    def get_all_tasks_status(self):
        statuses = []
        for task, completed in self.tasks.items():
            status_text = 'Completed' if completed else 'Pending'
            statuses.append(task + ' (' + status_text + ')')
        if not statuses:
            print(self.message_prefix + 'No tasks added yet.')
            return []
        all_tasks_display = ''
        for i, s in enumerate(statuses):
            all_tasks_display += s
            if i < len(statuses) - 1:
                all_tasks_display += '; '
        print(self.message_prefix + 'All tasks: ' + all_tasks_display + '.')
        return statuses

