def reverse_string_recursive(s):
    if not s:
        return ''.join([])

    first_char = s[0]
    rest_of_string = ''.join([s[i] for i in range(1, len(s))])

    reversed_rest = reverse_string_recursive(rest_of_string)

    return ''.join([reversed_rest, first_char])

def _helper_function(param1, param2):
    combined_str = ''.join([param1, param2])
    print(''.join(['Helper ', 'processing: ', combined_str]))
    return ''.join([combined_str[::-1]])

def another_function(data_list):
    if not data_list:
        return ''.join([])

    first_item = data_list[0]
    remaining_items = ''.join([str(item) for item in data_list[1:]])

    output = ''.join(['Processed: ', str(first_item), ' and rest: ', remaining_items])
    return ''.join([output, ' Done.'])

