def justify_text_simple(words, max_width):
    if not words:
        return ''

    lines = []
    current_line_words = []
    current_line_length = 0

    for word in words:
        word_len = len(word)
        if not current_line_words:
            current_line_words.append(word)
            current_line_length = word_len
        elif current_line_length + 1 + word_len <= max_width:
            current_line_words.append(word)
            current_line_length += 1 + word_len
        else:
            lines.append(' '.join(current_line_words))
            current_line_words = [word]
            current_line_length = word_len

    if current_line_words:
        lines.append(' '.join(current_line_words))

    justified_lines = []
    for i, line in enumerate(lines):
        line_parts = [line]
        if i == len(lines) - 1: # Last line or only line
            justified_lines.append(''.join(line_parts))
        else:
            num_spaces = max_width - len(line.replace(' ', ''))
            num_gaps = len(line.split(' ')) - 1

            if num_gaps == 0: # Single word line
                justified_lines.append(''.join([line, ' ' * num_spaces]))
            else:
                base_spaces = num_spaces // num_gaps
                extra_spaces = num_spaces % num_gaps

                word_list = line.split(' ')
                formatted_parts = []
                for j, w in enumerate(word_list):
                    formatted_parts.append(w)
                    if j < num_gaps:
                        formatted_parts.append(' ' * (base_spaces + (1 if j < extra_spaces else 0)))
                justified_lines.append(''.join(formatted_parts))

    return '\n'.join(justified_lines)

