def extract_domain(url):
    parts = url.split('/')
    domain_part = ''
    for part in parts:
        if '.' in part:
            domain_part = part
            break

    if domain_part.startswith('www.'):
        domain_part = domain_part[4:]

    domain_segments = domain_part.split('.')
    if len(domain_segments) > 1:
        main_domain = domain_segments[0]
    else:
        main_domain = domain_part

    if '?' in main_domain:
        main_domain = main_domain.split('?')[0]

    return ''.join([s for s in main_domain if s.isalnum() or s == '-'])

def extract_domain_enhanced(url):
    schemes = ['http://', 'https://', 'ftp://']
    for scheme in schemes:
        if url.startswith(scheme):
            url = url[len(scheme):]
            break

    parts = url.split('/')
    domain_part = parts[0]

    if domain_part.startswith('www.'):
        domain_part = ''.join([s for s in domain_part[4:]])

    domain_segments = domain_part.split('.')
    if len(domain_segments) > 1:
        main_domain = ''.join([domain_segments[0]])
    else:
        main_domain = ''.join([domain_part])

    if '?' in main_domain:
        main_domain = ''.join([s for s in main_domain.split('?')[0]])

    if '#' in main_domain:
        main_domain = ''.join([s for s in main_domain.split('#')[0]])

    return ''.join([s for s in main_domain if s.isalnum() or s == '-'])

